use xiom.io;
fn is_adult(age: Int) -> Bool {
  return age >= 18;
}

fn can_drive(age: Int) -> Bool {
  return age >= 16;
}

fn is_teenager(age: Int) -> Bool {
  return age >= 13 && age <= 19;
}

fn main() {
  let age = 15;
  io.println("Is 15 an adult? false");
  io.println("Can 15 drive? false");
  io.println("Is 15 a teenager? true");
}
